// src/lib/mcp/tools/list-room-types.ts
import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@0.25.0";
import { z as z3 } from "npm:zod@3.25.76";
var list_room_types_default = defineTool4({
  name: "list_room_types",
  title: "\u5217\u51FA\u623F\u578B\u8207\u65B9\u6848",
  description: "List room types and sales packages (including capacity and pricing) for one accommodation.",
  inputSchema: {
    accommodation_id: z3.string().uuid().describe("Accommodation UUID from list_accommodations.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ accommodation_id }, ctx) => {
    if (!ctx.isAuthenticated()) return errorResult("Not authenticated");
    const supabase = supabaseForUser(ctx);
    const [rooms, packages] = await Promise.all([
      supabase.from("room_types").select("id, name, capacity, base_price, room_count, is_exclusive_package, display_order").eq("accommodation_id", accommodation_id).order("display_order", { ascending: true }),
      supabase.from("accommodation_packages").select("id, name, subtitle, guest_count, guest_count_max, original_price, sale_price, enabled").eq("accommodation_id", accommodation_id).order("display_order", { ascending: true })
    ]);
    if (rooms.error) return errorResult(rooms.error.message);
    if (packages.error) return errorResult(packages.error.message);
    const payload = { room_types: rooms.data ?? [], packages: packages.data ?? [] };
    return { ...textResult(JSON.stringify(payload, null, 2)), structuredContent: payload };
  }
});

// src/lib/mcp/tools/revenue-summary.ts
import { defineTool as defineTool5 } from "npm:@lovable.dev/mcp-js@0.25.0";
import { z as z4 } from "npm:zod@3.25.76";
var revenue_summary_default = defineTool5({
  name: "revenue_summary",
  title: "\u71DF\u6536\u6982\u6CC1",
  description: "Summarise bookings for one accommodation over a check-in date range: order count, total revenue, paid amount and room nights. Cancelled orders are excluded.",
  inputSchema: {
    accommodation_id: z4.string().uuid().describe("Accommodation UUID from list_accommodations."),
    check_in_from: z4.string().describe("Start of the check-in range, YYYY-MM-DD."),
    check_in_to: z4.string().describe("End of the check-in range, YYYY-MM-DD.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async (input, ctx) => {
    if (!ctx.isAuthenticated()) return errorResult("Not authenticated");
    const { data, error } = await supabaseForUser(ctx).from("orders").select("final_price, paid_amount, check_in_date, check_out_date, order_status, order_source").eq("accommodation_id", input.accommodation_id).gte("check_in_date", input.check_in_from).lte("check_in_date", input.check_in_to).neq("order_status", "cancelled").limit(2e3);
    if (error) return errorResult(error.message);
    const rows = data ?? [];
    const nights = rows.reduce((sum, r) => {
      const inD = new Date(r.check_in_date).getTime();
      const outD = new Date(r.check_out_date).getTime();
      return sum + Math.max(0, Math.round((outD - inD) / 864e5));
    }, 0);
    const bySource = {};
    for (const r of rows) {
      const key = r.order_source ?? "unknown";
      bySource[key] = (bySource[key] ?? 0) + Number(r.final_price ?? 0);
    }
    const summary = {
      order_count: rows.length,
      total_revenue: rows.reduce((s, r) => s + Number(r.final_price ?? 0), 0),
      paid_amount: rows.reduce((s, r) => s + Number(r.paid_amount ?? 0), 0),
      room_nights: nights,
      revenue_by_source: bySource
    };
    return { ...textResult(JSON.stringify(summary, null, 2)), structuredContent: summary };
  }
});

